import { tags } from "typia";

import { ISearchHealthMetric } from "./ISearchHealthMetric";

/**
 * Health status response for the product search service, indicating whether the search index is accessible and operational. Used by monitoring systems and load balancers to verify search functionality availability.
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISearchHealthStatus = {
  /**
   * Current health status of the search index service.
   *
   * @x-autobe-specification Computed from index accessibility and staleness: 'healthy' if table accessible and last updated within 1 hour, 'degraded' if accessible but last updated >1 hour ago, 'unhealthy' if table inaccessible. Logic: Check database connectivity → Query MAX(updated_at) → Compare to current time → Determine status level.
   */
  status: "healthy" | "degraded" | "unhealthy";

  /**
   * Timestamp of the last search index update.
   *
   * @x-autobe-specification Computed as MAX(updated_at) from ecommerce_mall_search_indices table. Returns null if table is inaccessible. Format: RFC3339 date-time string (ISO 8601 with timezone). This provides the most recent index modification time for freshness monitoring.
   */
  lastUpdated: string & tags.Format<"date-time">;

  /**
   * Optional health metrics about the search index.
   *
   * @x-autobe-specification Computed aggregated metrics including: total indexed item count (COUNT(*) FROM ecommerce_mall_search_indices WHERE deleted_at IS NULL), index availability status, and freshness calculations (time since last updated). This is optional (nullable) to allow minimal responses when metrics aren't available or not needed. The ISearchHealthMetric schema provides structure for these aggregated values.
   */
  metrics: ISearchHealthMetric | null;
};
